syntax:
template <typename T> 
ReturnType functionName(T param); 

// Full specialization
template <> 
ReturnType functionName<SpecificType>(SpecificType param); 

// Partial specialization (for class templates, not functions)
// Not applicable for function templates directly, but can be achieved via SFINAE or tag dispatching.

code_example:
#include <iostream>
template <typename T>
void printType(const T& value) {
    std::cout << "Generic template: " << value << std::endl;
}

// Specialization for int
template <>
void printType<int>(const int& value) {
    std::cout << "Integer specialization: " << value << std::endl;
}

int main() {
    printType(3.14); // Calls generic template
    printType(42);   // Calls specialized template for int
    return 0;
}
